import {ownerAuthCopy} from './owner-auth-copy.js?v=5.11.0';
export const OWNER_BOOK={
 ko:{overview:'사장님은 샵 비밀번호를 설정하고 로그인합니다. 기존 샵의 첫 설정은 관리 권한이 있는 기기에서만 가능합니다. 관리 링크와 비밀번호로 다른 기기에서도 같은 샵과 주문을 봅니다.',access:'손님 링크로 사장님 화면에 들어갈 수 없습니다. 직원은 발급받은 자기 링크로 허용된 데이터와 기능만 이용합니다. 로그아웃하면 해당 관리 세션이 폐기되고, 비밀번호를 바꾸면 다른 사장님 세션도 해제됩니다.',boundary:'사장님 비밀번호는 서버에서 검증합니다. 직원은 링크 기반 접근이며 직원 본인 인증과 이메일 비밀번호 복구는 아직 미연결입니다. 실제 AI와 결제는 연결하지 않았습니다.',demo:'프로덕션북의 네 화면 시연은 가입 없이 볼 수 있는 가상 시나리오입니다. 별도의 사장님앱에서는 비밀번호를 정해 주모 메뉴와 샘플 주문·예약이 들어 있는 자신의 데모 샵을 만듭니다.'},
 en:{overview:'Owners set a shop password and sign in. An existing shop’s first password can only be set from an authorized management device. The management link and password open the same shop and orders on other devices.',access:'Guest links do not grant owner access. Staff use their own issued links and receive only permitted data and actions. Signing out revokes that session; changing the password ends other owner sessions.',boundary:'Owner passwords are verified on the server. Staff access is link-based; verified staff identity and email password recovery are not connected yet. Real AI and payment remain disconnected.',demo:'The four-screen book showcase is a public scripted presentation. In the separate owner app, set a password to create your own demo shop with Jumo’s menu, sample orders and bookings.'},
 vi:{overview:'Chủ quán đặt mật khẩu cho quán và đăng nhập. Với quán đã có, chỉ thiết bị được cấp quyền quản lý mới được đặt mật khẩu lần đầu. Liên kết quản lý và mật khẩu giúp mở cùng quán và đơn hàng trên thiết bị khác.',access:'Liên kết khách không cấp quyền chủ quán. Nhân viên dùng liên kết riêng và chỉ xem dữ liệu, thao tác được cho phép. Đăng xuất hủy phiên hiện tại; đổi mật khẩu kết thúc các phiên chủ quán khác.',boundary:'Mật khẩu chủ quán được xác minh trên máy chủ. Nhân viên truy cập bằng liên kết; chưa có xác minh danh tính hay khôi phục mật khẩu qua email. Chưa kết nối AI và thanh toán thật.',demo:'Phần trình diễn bốn màn hình trong sách dự án dùng kịch bản mẫu và xem được không cần đăng ký. Ở ứng dụng chủ quán riêng, đặt mật khẩu để tạo quán demo của bạn với thực đơn Jumo, đơn và đặt bàn mẫu.'},
 zh:{overview:'店主设置店铺密码后登录。已有店铺仅可在原有授权管理设备上首次设置密码。在其他设备上使用管理链接和密码，可查看同一店铺与订单。',access:'顾客链接不提供店主权限。员工使用各自专属链接，仅访问获准的数据和操作。退出会撤销当前会话，修改密码会结束其他店主会话。',boundary:'店主密码由服务器验证。员工采用专属链接访问，尚未接入员工实名验证或邮件密码找回。真实AI和支付仍未连接。',demo:'项目书的四屏演示是无需注册的公开情景示范。在独立的店主应用中，设置密码即可创建自己的演示店铺，内含Jumo菜单与示例订单、订位。'},
 ja:{overview:'オーナーは店舗のパスワードを設定してログインします。既存店舗の初回設定は管理権限のある端末に限ります。管理リンクとパスワードで別の端末からも同じ店舗や注文を確認できます。',access:'お客様のリンクでは管理権限は得られません。スタッフは専用リンクを使い、許可された情報と操作だけを利用します。ログアウトでそのセッションを終了し、パスワード変更で他の管理セッションも終了します。',boundary:'オーナーのパスワードはサーバーで確認します。スタッフはリンクによるアクセスで、本人確認とメールでのパスワード復旧は未対応です。実際のAIと決済は接続していません。',demo:'ブックの4画面デモは登録不要の公開シナリオです。別のオーナーアプリではパスワードを設定し、Jumoのメニューと注文・予約サンプルが入った専用デモ店舗を作成します。'},
 id:{overview:'Pemilik mengatur kata sandi kedai lalu masuk. Kata sandi pertama kedai yang sudah ada hanya dapat dibuat dari perangkat pengelola yang berwenang. Tautan pengelolaan dan kata sandi membuka kedai serta pesanan yang sama di perangkat lain.',access:'Tautan tamu tidak memberi akses pemilik. Staf memakai tautan masing-masing dan hanya mendapat data serta tindakan yang diizinkan. Keluar mengakhiri sesi tersebut; mengganti kata sandi mengakhiri sesi pemilik lainnya.',boundary:'Kata sandi pemilik diperiksa di server. Akses staf berbasis tautan; verifikasi identitas staf dan pemulihan kata sandi melalui email belum terhubung. AI dan pembayaran sungguhan belum terhubung.',demo:'Peragaan empat layar di buku proyek adalah skenario publik tanpa pendaftaran. Di aplikasi pemilik terpisah, buat kata sandi untuk kedai demo Anda dengan menu Jumo, contoh pesanan dan reservasi.'},
 hi:{overview:'मालिक दुकान का पासवर्ड बनाकर लॉगिन करते हैं। मौजूदा दुकान का पहला पासवर्ड सिर्फ अधिकृत प्रबंधन डिवाइस पर बन सकता है। प्रबंधन लिंक और पासवर्ड से दूसरे डिवाइस पर वही दुकान और ऑर्डर दिखते हैं।',access:'मेहमान के लिंक से मालिक की अनुमति नहीं मिलती। कर्मचारी अपने अलग लिंक पर केवल अनुमति वाले डेटा और काम देख सकते हैं। लॉगआउट से वही सत्र खत्म होता है; पासवर्ड बदलने से बाकी मालिक सत्र भी खत्म होते हैं।',boundary:'मालिक का पासवर्ड सर्वर पर जाँचा जाता है। कर्मचारियों का प्रवेश लिंक आधारित है; पहचान की पुष्टि और ईमेल से पासवर्ड रिकवरी अभी नहीं जुड़े हैं। असली AI और भुगतान भी नहीं जुड़े हैं।',demo:'बुक का चार-स्क्रीन प्रदर्शन बिना पंजीकरण का सार्वजनिक नमूना है। अलग मालिक ऐप में पासवर्ड बनाकर Jumo मेन्यू, नमूना ऑर्डर और बुकिंग वाली अपनी डेमो दुकान शुरू करें।'},
 km:{overview:'ម្ចាស់ហាងកំណត់ពាក្យសម្ងាត់ហើយចូលប្រើ។ សម្រាប់ហាងចាស់ មានតែឧបករណ៍គ្រប់គ្រងដែលមានសិទ្ធិប៉ុណ្ណោះអាចកំណត់ពាក្យសម្ងាត់ដំបូង។ ប្រើតំណគ្រប់គ្រងនិងពាក្យសម្ងាត់ដើម្បីមើលហាងនិងបញ្ជាទិញដដែលពីឧបករណ៍ផ្សេង។',access:'តំណភ្ញៀវមិនផ្ដល់សិទ្ធិម្ចាស់ហាងទេ។ បុគ្គលិកប្រើតំណផ្ទាល់ខ្លួន ហើយមើលតែទិន្នន័យនិងមុខងារដែលអនុញ្ញាត។ ការចាកចេញបញ្ចប់វគ្គនោះ ហើយការប្ដូរពាក្យសម្ងាត់បញ្ចប់វគ្គម្ចាស់ហាងផ្សេងទៀត។',boundary:'ពាក្យសម្ងាត់ម្ចាស់ហាងត្រូវបានពិនិត្យលើម៉ាស៊ីនមេ។ បុគ្គលិកចូលតាមតំណ។ មិនទាន់មានការផ្ទៀងផ្ទាត់អត្តសញ្ញាណ ឬស្ដារពាក្យសម្ងាត់តាមអ៊ីមែលទេ។ មិនភ្ជាប់ AI ឬការទូទាត់ពិតទេ។',demo:'ការបង្ហាញបួនអេក្រង់ក្នុងសៀវភៅជាសេណារីយ៉ូសាធារណៈ មិនត្រូវការចុះឈ្មោះ។ ក្នុងកម្មវិធីម្ចាស់ហាងដាច់ដោយឡែក អ្នកកំណត់ពាក្យសម្ងាត់ដើម្បីបង្កើតហាងសាកល្បងផ្ទាល់ខ្លួន ដែលមានម៉ឺនុយ Jumo និងគំរូបញ្ជាទិញនិងការកក់។'},
 lo:{overview:'ເຈົ້າຂອງຕັ້ງລະຫັດຜ່ານຮ້ານແລ້ວເຂົ້າລະບົບ. ຮ້ານເກົ່າຕັ້ງລະຫັດຄັ້ງທຳອິດໄດ້ສະເພາະໃນອຸປະກອນຈັດການທີ່ມີສິດ. ໃຊ້ລິ້ງຈັດການແລະລະຫັດຜ່ານເພື່ອເບິ່ງຮ້ານແລະອໍເດີດຽວກັນຈາກອຸປະກອນອື່ນ.',access:'ລິ້ງລູກຄ້າບໍ່ໃຫ້ສິດເຈົ້າຂອງ. ພະນັກງານໃຊ້ລິ້ງຂອງຕົນ ແລະເຫັນສະເພາະຂໍ້ມູນແລະຄຳສັ່ງທີ່ອະນຸຍາດ. ອອກລະບົບແລ້ວເຊດຊັນນັ້ນຈະສິ້ນສຸດ; ປ່ຽນລະຫັດແລ້ວເຊດຊັນເຈົ້າຂອງອື່ນກໍສິ້ນສຸດ.',boundary:'ລະຫັດເຈົ້າຂອງຖືກກວດສອບທີ່ເຊີບເວີ. ພະນັກງານເຂົ້າຜ່ານລິ້ງ; ຍັງບໍ່ມີການຢືນຢັນຕົວຕົນ ຫຼືກູ້ລະຫັດຜ່ານທາງອີເມວ. ບໍ່ໄດ້ເຊື່ອມ AI ຫຼືການຊຳລະຈິງ.',demo:'ການສາທິດສີ່ໜ້າຈໍໃນປຶ້ມເປັນສະຖານະການຕົວຢ່າງສາທາລະນະ ບໍ່ຕ້ອງສະໝັກ. ໃນແອັບເຈົ້າຂອງແຍກຕ່າງຫາກ ຕັ້ງລະຫັດເພື່ອສ້າງຮ້ານທົດລອງຂອງຕົນ ພ້ອມເມນູ Jumo ແລະຕົວຢ່າງອໍເດີແລະການຈອງ.'}
};
export function applyOwnerBook(book){for(const [lang,b] of Object.entries(book)){const c=OWNER_BOOK[lang],a=ownerAuthCopy(lang);for(const section of b.sections){if(section.id==='onboarding'){section.paragraphs=[c.demo,c.overview];section.points=[a.setup,a.login,a.security];}if(section.id==='trust')section.paragraphs[1]=c.access+' '+c.boundary;if(section.id==='roadmap'){section.paragraphs[0]=c.overview+' '+c.boundary;section.points[2]=a.security;}if(section.id==='workshop'){section.paragraphs[1]=c.access;section.points[2]=a.security;}if(section.id==='faq')section.paragraphs[0]=c.demo+' '+c.overview;}}return book;}
